<include file="Public:header"/><style type="text/css">    .table-list th{        width: 8%;    }</style><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Qiye/lists')}">企业列表</a>|					<a href="javascript:void(0);" class="on">员工列表</a>				</ul>			</div>				<div class="table-list">					<table width="100%" cellspacing="0">						<thead>							<tr>                                <th>{pigcms{:L_("卡号/工号/ID")}</th>                                <th>{pigcms{:L_("姓名")}</th>                                <th>{pigcms{:L_("UID")}</th>                                <th>{pigcms{:L_("手机号码")}</th>                                <th class="text-middle">{pigcms{:L_("预存余额")}</th>                                <th class="text-middle">{pigcms{:L_("实体卡ID")}</th>                                <th class="text-middle">{pigcms{:L_("员工组别")}</th>                                <th class="text-middle">{pigcms{:L_("备注")}</th>                                <th class="text-middle">{pigcms{:L_("录入时间")}</th>                                <th class="text-middle">{pigcms{:L_("状态")}</th>						</thead>						<tbody>                        <notempty name="staffs">                            <volist name="staffs" id="s">                                <tr>                                    <td>{pigcms{$s.staff_number}</td>                                    <td>{pigcms{$s.name}</td>                                    <td>                                        <if condition="$s['job_number'] EQ 0">                                            <a title="点击扫码绑定平台用户"                                               href="{pigcms{$config.site_url}/index.php?g=Index&c=Recognition&a=see_qrcode&type=qiyeStaff&id={pigcms{$s['staff_id']}&img=1"                                               class="see_qrcode" data-name="{pigcms{$s.name}">扫码绑定用户</a>                                            <else/>                                            {pigcms{$s.job_number}                                        </if>                                    </td>                                    <td>{pigcms{$s.phone}</td>                                    <td class="text-middle">{pigcms{$s.money} <gt name="s.unpaid_money" value="0"><font color="red">({pigcms{$s.unpaid_money}未到账)</font></gt></td>                                    <td class="text-middle">{pigcms{$s.card_id}</td>                                    <td class="text-middle">{pigcms{$s.group_name}</td>                                    <td class="text-middle">{pigcms{$s.remark}</td>                                    <td class="text-middle">                                        <if condition="$s['create_time'] gt 0">{pigcms{$s.create_time|date='Y-m-d                                            H:i:s',###}                                        </if>                                    </td>                                    <td class="text-middle">                                        <if condition="$s['status'] eq 1">正常                                            <else/>                                            禁用                                        </if>                                    </td>                                </tr>                            </volist>                            <tr><td class="textcenter pagebar" colspan="15">{pigcms{$pagebar}</td></tr>                            <else/>                            <tr><td class="textcenter red" colspan="15">列表为空！</td></tr>                        </notempty>						</tbody>					</table>				</div>				</div><script>  function add_qiye(){      window.top.artiframe('{pigcms{:U('Qiye/add')}','添加企业',800,500,true,false,false,addbtn,'add',true);  }  function qiye_edit(id){      window.top.artiframe('{pigcms{:U('Qiye/edit')}'+'&qiye_id='+id,'编辑企业',800,500,true,false,false,addbtn,'add',true);  }</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>